/bin/bash -lc "node --input-type=module - <<'EOF'
const CHARSET='qpzry9x8gf2tvdw0s3jn54khce6mua7l';
const GEN=[0x3b6a57b2,0x26508e6d,0x1ea119fa,0x3d4233dd,0x2a1462b3];
function polymod(values){let chk=1;for(const v of values){const top=chk>>25;chk=((chk&0x1ffffff)<<5)"'^v;for(let i=0;i<5;i++) if((top>>i)&1) chk''^=GEN[i];}return chk>>>0;}
function hrpExpand(hrp){const out=[];for(const ch of hrp){out.push(ch.charCodeAt(0)>>5);} out.push(0); for(const ch of hrp){out.push(ch.charCodeAt(0)&31);} return out;}
function checksum(hrp,data,constXor){const values=hrpExpand(hrp).concat(data).concat([0,0,0,0,0,0]); const mod=(polymod(values)''^constXor)>>>0; const out=[]; for(let p=25;p>=0;p-=5) out.push((mod>>p)&31); return out;}
function encode(hrp,data,constXor){return hrp+'"'1'+data.concat(checksum(hrp,data,constXor)).map(v=>CHARSET[v]).join('');}
function convertbits(data,frombits,tobits,pad=true){let acc=0,bits=0;const ret=[];const maxv=(1<<tobits)-1;const maxAcc=(1<<(frombits+tobits-1))-1;for(const value of data){if(value<0 || (value>>frombits)"'!==0) return null; acc=((acc<<frombits)|value)&maxAcc; bits+=frombits; while(bits>=tobits){ bits-=tobits; ret.push((acc>>bits)&maxv);} } if(pad){ if(bits) ret.push((acc<<(tobits-bits))&maxv);} else if(bits>=frombits || ((acc<<(tobits-bits))&maxv)) return null; return ret; }
const hrp='"'ltc'; const ver=1; const prog='14,9,1,16,26,18,9,12,21,14,24,15,31,21,16,31,31,29,10,22,10,8,31,11,3,2,4,3,0,26,8,14'.split(',').map(Number); const data=[ver].concat(convertbits(prog,8,5,true));
console.log('bech32', encode(hrp,data,1));
console.log('bech32m', encode(hrp,data,0x2bc830a3));
EOF"

